# region src/Private/Common.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

$script:WinToolPublishedUrl = "https://raw.githubusercontent.com/Hinrikao/WinTool/main/wintool.ps1"
$script:WinToolProfileBegin = "# >>> WinTool terminal setup >>>"
$script:WinToolProfileEnd = "# <<< WinTool terminal setup <<<"

if ([string]::IsNullOrWhiteSpace($script:WinToolVersion)) {
    $script:WinToolVersion = "1.0.0"
}

function Get-WinToolNote {
    param(
        $Object,
        [Parameter(Mandatory = $true)][string]$Name,
        $Default = $null
    )
    if ($null -eq $Object) {
        return $Default
    }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property -or $null -eq $property.Value) {
        return $Default
    }
    return $property.Value
}

function Test-WinToolWindows {
    return ($env:OS -eq "Windows_NT")
}

function Test-WinToolTextMatch {
    param(
        [string]$Haystack,
        [string]$Query
    )
    if ([string]::IsNullOrWhiteSpace($Query)) {
        return $true
    }
    if ([string]::IsNullOrWhiteSpace($Haystack)) {
        return $false
    }
    return ($Haystack.IndexOf($Query.Trim(), [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function ConvertFrom-WinToolEmbeddedPayload {
    param(
        [Parameter(Mandatory = $true)][byte[]]$Bytes
    )
    if ($null -eq $Bytes -or $Bytes.Length -lt 2) {
        return [System.Text.Encoding]::UTF8.GetString($Bytes)
    }
    # Gzip magic 1F 8B. Older builds stored raw UTF-8.
    if ($Bytes[0] -eq 0x1F -and $Bytes[1] -eq 0x8B) {
        $sourceStream = New-Object System.IO.MemoryStream(,$Bytes)
        $gzip = New-Object System.IO.Compression.GzipStream($sourceStream, [System.IO.Compression.CompressionMode]::Decompress)
        try {
            $output = New-Object System.IO.MemoryStream
            $gzip.CopyTo($output)
            return [System.Text.Encoding]::UTF8.GetString($output.ToArray())
        }
        finally {
            $gzip.Dispose()
            $sourceStream.Dispose()
        }
    }
    return [System.Text.Encoding]::UTF8.GetString($Bytes)
}

function Get-WinToolPayloadText {
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )
    $embedded = $script:WinToolEmbedded
    if ($null -ne $embedded -and $embedded.ContainsKey($Name)) {
        $clean = ([string]$embedded[$Name]) -replace '\s', ''
        $bytes = [Convert]::FromBase64String($clean)
        return (ConvertFrom-WinToolEmbeddedPayload -Bytes $bytes)
    }

    if ([string]::IsNullOrWhiteSpace($script:WinToolRoot)) {
        throw (Get-WinToolText "msg.wintool-payload-n-is-not-embedded-and-no-source-folder-i" $Name)
    }

    $relative = @{
        Apps = "data/apps.json"
        Tweaks = "data/tweaks.json"
        Terminal = "data/terminal.json"
        Fonts = "data/fonts.json"
        OmpThemes = "data/omp-themes.json"
        Updates = "data/updates.json"
        Drivers = "data/drivers.json"
        Fixes = "data/fixes.json"
        Features = "data/features.json"
        System = "data/system.json"
        Xaml = "assets/MainWindow.xaml"
        Wsl = "data/wsl-setup.sh"
    }
    if (-not $relative.ContainsKey($Name)) {
        throw (Get-WinToolText "msg.unknown-wintool-payload-n" $Name)
    }

    $path = Join-Path $script:WinToolRoot $relative[$Name]
    return [System.IO.File]::ReadAllText($path)
}

function Get-WinToolLogPath {
    if (-not [string]::IsNullOrWhiteSpace($script:WinToolLogFile)) {
        return $script:WinToolLogFile
    }
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    $directory = Join-Path $env:LOCALAPPDATA "WinTool/logs"
    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $name = "wintool-" + (Get-Date -Format "yyyyMMdd-HHmmss") + ".log"
    $script:WinToolLogFile = Join-Path $directory $name
    return $script:WinToolLogFile
}

function Add-WinToolLogLine {
    param(
        [Parameter(Mandatory = $true)][string]$Line
    )
    $path = Get-WinToolLogPath
    if (-not [string]::IsNullOrWhiteSpace($path)) {
        try {
            Add-Content -LiteralPath $path -Value $Line -Encoding UTF8
        }
        catch {
            $null = $_.Exception.Message
        }
    }

    if ($null -eq $script:WinToolLogBox) {
        if ($null -eq $script:WinToolWindow) {
            Write-Host $Line
        }
        return
    }

    $box = $script:WinToolLogBox
    $write = {
        $box.AppendText($Line + [Environment]::NewLine)
        $box.ScrollToEnd()
    }.GetNewClosure()

    if ($box.Dispatcher.CheckAccess()) {
        & $write
    }
    else {
        $box.Dispatcher.BeginInvoke([System.Action]$write) | Out-Null
    }
}

function Write-WinToolLog {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message,
        [ValidateSet("info", "ok", "warn", "error")]
        [string]$Level = "info",
        # Also append to %TEMP%\WinTool\wintool.log, the file people send in bug reports.
        [switch]$Diagnostic
    )
    if ([string]::IsNullOrWhiteSpace($Message)) {
        return
    }
    if ($null -ne $script:WinToolHelperLogCallback) {
        try {
            & $script:WinToolHelperLogCallback $Message $Level
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    $prefix = "INFO"
    if ($Level -eq "ok") { $prefix = " OK " }
    elseif ($Level -eq "warn") { $prefix = "WARN" }
    elseif ($Level -eq "error") { $prefix = "FAIL" }
    $stamp = Get-Date -Format "HH:mm:ss"
    $line = "{0}  {1}  {2}" -f $stamp, $prefix, $Message
    Add-WinToolLogLine -Line $line
    if ($Diagnostic) {
        Write-WinToolDiagnosticLine -Line $line
    }
    if ($script:WinToolHasActivity) {
        $stepStatus = $Level
        if ($Level -eq "info") { $stepStatus = "ok" }
        Add-WinToolActivityStep -Status $stepStatus -Message $Message | Out-Null
    }
}

function Write-WinToolDiagnosticLine {
    param(
        [Parameter(Mandatory = $true)][string]$Line,
        [string]$Path
    )
    try {
        if ([string]::IsNullOrWhiteSpace($Path)) {
            if ([string]::IsNullOrWhiteSpace($env:TEMP)) {
                return
            }
            $directory = Join-Path $env:TEMP "WinTool"
            if (-not (Test-Path -LiteralPath $directory)) {
                New-Item -ItemType Directory -Path $directory -Force | Out-Null
            }
            $Path = Join-Path $directory "wintool.log"
        }
        Add-Content -LiteralPath $Path -Value ((Get-Date -Format "yyyy-MM-dd ") + $Line) -Encoding UTF8
    }
    catch {
        $null = $_.Exception.Message
    }
}

function ConvertTo-WinToolArgumentLine {
    param(
        [string[]]$ArgumentList
    )
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($argument in @($ArgumentList)) {
        if ($null -eq $argument) {
            continue
        }
        $text = [string]$argument
        if ($text -match '[\s"]') {
            $escaped = $text.Replace('"', '\"')
            $parts.Add('"' + $escaped + '"')
        }
        else {
            $parts.Add($text)
        }
    }
    return ($parts -join " ")
}

function Format-WinToolErrorText {
    param(
        $ErrorRecord,
        [string]$Title = (Get-WinToolText "error.couldNotStart")
    )
    if ($null -eq $ErrorRecord) {
        return $Title
    }
    $body = ""
    try {
        $body = ($ErrorRecord | Out-String).Trim()
    }
    catch {
        $body = [string]$ErrorRecord
    }
    if ([string]::IsNullOrWhiteSpace($body) -and $null -ne $ErrorRecord.Exception) {
        $body = [string]$ErrorRecord.Exception.Message
    }
    $text = $Title + "`r`n`r`n" + $body
    $stack = [string]$ErrorRecord.ScriptStackTrace
    if (-not [string]::IsNullOrWhiteSpace($stack)) {
        $text += "`r`n`r`n" + $stack
    }
    return $text
}

function Write-WinToolFailureLog {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text,
        [string]$Path
    )
    if ([string]::IsNullOrWhiteSpace($Path)) {
        $directory = Join-Path $env:TEMP "WinTool"
        if (-not (Test-Path -LiteralPath $directory)) {
            New-Item -ItemType Directory -Path $directory -Force | Out-Null
        }
        $Path = Join-Path $directory "wintool.log"
    }
    else {
        $directory = Split-Path -Parent $Path
        if (-not [string]::IsNullOrWhiteSpace($directory) -and -not (Test-Path -LiteralPath $directory)) {
            New-Item -ItemType Directory -Path $directory -Force | Out-Null
        }
    }
    $stamp = [DateTime]::UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ")
    $block = "==== $stamp ====`r`n" + $Text + "`r`n"
    Add-Content -LiteralPath $Path -Value $block -Encoding UTF8
    return $Path
}

function Show-WinToolFailure {
    param(
        $ErrorRecord
    )
    try {
        Show-WinToolConsole
    }
    catch {
        $null = $_.Exception.Message
    }
    $text = Format-WinToolErrorText -ErrorRecord $ErrorRecord
    $path = $null
    try {
        $path = Write-WinToolFailureLog -Text $text
    }
    catch {
        $path = $null
    }
    Write-Host ""
    Write-Host $text
    if (-not [string]::IsNullOrWhiteSpace($path)) {
        Write-Host ""
        Write-Host (Get-WinToolText "error.logPath" $path)
    }
    try {
        Add-Type -AssemblyName PresentationFramework -ErrorAction Stop
        $dialog = $text
        if (-not [string]::IsNullOrWhiteSpace($path)) {
            $dialog += "`r`n`r`nLog: $path"
        }
        if ($dialog.Length -gt 3500) {
            $dialog = $dialog.Substring(0, 3500) + "..."
        }
        [System.Windows.MessageBox]::Show($dialog, "WinTool") | Out-Null
    }
    catch {
        Write-Host $_.Exception.Message
    }
    if ($env:WINTOOL_PAUSE_ON_ERROR -eq "1") {
        Write-Host ""
        Write-Host (Get-WinToolText "error.pressEnter")
        Read-Host | Out-Null
        exit 1
    }
}

function Write-WinToolUtf8File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text,
        [switch]$Bom
    )
    $encoding = New-Object System.Text.UTF8Encoding ([bool]$Bom)
    [System.IO.File]::WriteAllText($Path, $Text, $encoding)
}
# endregion

# region src/Private/Json.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function ConvertTo-WinToolJsonString {
    param(
        [AllowNull()][string]$Text
    )
    if ($null -eq $Text) {
        return "null"
    }
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.Append('"')
    foreach ($char in $Text.ToCharArray()) {
        $code = [int]$char
        if ($code -eq 34) {
            [void]$builder.Append('\"')
        }
        elseif ($code -eq 92) {
            [void]$builder.Append('\\')
        }
        elseif ($code -eq 8) {
            [void]$builder.Append('\b')
        }
        elseif ($code -eq 12) {
            [void]$builder.Append('\f')
        }
        elseif ($code -eq 10) {
            [void]$builder.Append('\n')
        }
        elseif ($code -eq 13) {
            [void]$builder.Append('\r')
        }
        elseif ($code -eq 9) {
            [void]$builder.Append('\t')
        }
        elseif ($code -lt 32) {
            [void]$builder.Append('\u')
            [void]$builder.Append($code.ToString("x4"))
        }
        else {
            [void]$builder.Append($char)
        }
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function ConvertTo-WinToolJsonText {
    param(
        $Value,
        [int]$Indent = 0
    )
    $pad = " " * ($Indent * 2)
    $next = $Indent + 1
    $inner = " " * ($next * 2)

    if ($null -eq $Value) {
        return "null"
    }
    if ($Value -is [string]) {
        return (ConvertTo-WinToolJsonString -Text $Value)
    }
    if ($Value -is [bool]) {
        if ($Value) { return "true" }
        return "false"
    }
    if ($Value -is [ValueType]) {
        return [Convert]::ToString($Value, [System.Globalization.CultureInfo]::InvariantCulture)
    }

    $isCustom = $Value -is [System.Management.Automation.PSCustomObject]
    if (-not $isCustom -and $Value -is [System.Collections.IDictionary]) {
        $names = @($Value.Keys)
        if ($names.Count -eq 0) {
            return "{}"
        }
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($name in $names) {
            $encoded = ConvertTo-WinToolJsonString -Text ([string]$name)
            $child = ConvertTo-WinToolJsonText -Value $Value[$name] -Indent $next
            $lines.Add($inner + $encoded + ": " + $child)
        }
        return "{`n" + ($lines -join ",`n") + "`n" + $pad + "}"
    }

    if (-not $isCustom -and $Value -is [System.Collections.IEnumerable]) {
        $items = @($Value)
        if ($items.Count -eq 0) {
            return "[]"
        }
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($item in $items) {
            $lines.Add($inner + (ConvertTo-WinToolJsonText -Value $item -Indent $next))
        }
        return "[`n" + ($lines -join ",`n") + "`n" + $pad + "]"
    }

    $properties = @($Value.PSObject.Properties)
    if ($properties.Count -eq 0) {
        return "{}"
    }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($property in $properties) {
        $encoded = ConvertTo-WinToolJsonString -Text ([string]$property.Name)
        $child = ConvertTo-WinToolJsonText -Value $property.Value -Indent $next
        $lines.Add($inner + $encoded + ": " + $child)
    }
    return "{`n" + ($lines -join ",`n") + "`n" + $pad + "}"
}

function ConvertTo-WinToolPlainJson {
    param(
        [AllowEmptyString()][string]$Text
    )
    if ([string]::IsNullOrEmpty($Text)) {
        return $Text
    }
    $builder = New-Object System.Text.StringBuilder
    $chars = $Text.ToCharArray()
    $inString = $false
    $escape = $false
    $index = 0
    while ($index -lt $chars.Length) {
        $char = $chars[$index]
        if ($inString) {
            [void]$builder.Append($char)
            if ($escape) {
                $escape = $false
            }
            elseif ($char -eq '\') {
                $escape = $true
            }
            elseif ($char -eq '"') {
                $inString = $false
            }
            $index++
            continue
        }
        if ($char -eq '"') {
            $inString = $true
            [void]$builder.Append($char)
            $index++
            continue
        }
        if ($char -eq '/' -and ($index + 1) -lt $chars.Length) {
            $next = $chars[$index + 1]
            if ($next -eq '/') {
                $index += 2
                while ($index -lt $chars.Length -and $chars[$index] -ne "`n") {
                    $index++
                }
                continue
            }
            if ($next -eq '*') {
                $index += 2
                while (($index + 1) -lt $chars.Length -and -not ($chars[$index] -eq '*' -and $chars[$index + 1] -eq '/')) {
                    $index++
                }
                if (($index + 1) -lt $chars.Length) {
                    $index += 2
                }
                else {
                    $index = $chars.Length
                }
                continue
            }
        }
        [void]$builder.Append($char)
        $index++
    }
    return [regex]::Replace($builder.ToString(), ',(?=\s*[}\]])', '')
}

function ConvertFrom-WinToolJsonText {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text
    )
    $plain = ConvertTo-WinToolPlainJson -Text $Text
    if ([string]::IsNullOrWhiteSpace($plain)) {
        throw (Get-WinToolText "msg.the-json-text-was-empty")
    }
    return ($plain | ConvertFrom-Json)
}

function Read-WinToolJsonFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    $text = [System.IO.File]::ReadAllText($Path)
    return (ConvertFrom-WinToolJsonText -Text $text)
}

function Write-WinToolJsonFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)]$Value
    )
    $json = ConvertTo-WinToolJsonText -Value $Value
    Write-WinToolUtf8File -Path $Path -Text ($json + "`n")
}
# endregion

